async function putInspectorLayout<T extends { id: string }>(prefix: string, layout: T): Promise<T> {
  const response = await fetch(prefix + encodeURIComponent(layout.id), { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(layout) });
  if (!response.ok) { const body = await response.json().catch(() => null); throw new Error(body?.error ?? `${response.status} ${response.statusText}`); }
  return response.json();
}

export async function saveInspectorLayouts(layouts: InspectorLayout[]): Promise<InspectorLayout[]> {
  const response = await fetch("/api/inspector-layouts", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(layouts)
  });
  if (!response.ok) throw new Error(response.status + " " + response.statusText);
  return response.json() as Promise<InspectorLayout[]>;
}

